func HasIncludesWith(preds ...predicate.BlueprintInclude) predicate.Blueprint {
	return predicate.Blueprint(func(s *sql.Selector) {
		step := newIncludesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

